import sys
from collections import defaultdict

class IntIntPair:
    def __init__(self, first, second):
        self.first = first
        self.second = second

    def __eq__(self, o):
        if self is o:
            return True
        if o is None or not isinstance(o, IntIntPair):
            return False
        return self.first == o.first and self.second == o.second

    def __hash__(self):
        return hash(self.first) * 31 + hash(self.second)

class TaskC:
    BAD = 11111

    def __init__(self):
        self.rows = 0
        self.cols = 0
        self.mem = []

    def contains(self, mem, index):
        if index < 0:
            return False
        return ((mem >> index) & 1) == 1

    def add(self, mem, index):
        if ((mem >> index) & 1) == 0:
            mem += (1 << index)
        return mem

    def size(self, mem):
        count = 0
        while mem > 0:
            count += mem & 1
            mem >>= 1
        return count

    def test(self):
        if self.contains(5, 0) != False:
            raise RuntimeError()
        if self.contains(5, 1) != True:
            raise RuntimeError()
        if self.contains(5, -1) != False:
            raise RuntimeError()
        if self.contains(5, 2) != True:
            raise RuntimeError()
        if self.contains(5, 3) != False:
            raise RuntimeError()
        if self.add(0, 2) != 4:
            raise RuntimeError()
        if self.add(4, 0) != 5:
            raise RuntimeError()
        if self.add(5, 0) != 5:
            raise RuntimeError()
        if self.size(5) != 2:
            raise RuntimeError()

    def dp(self, row, remabove, squareabove):
        if row == self.rows:
            if remabove == 0:
                return 0
            return self.BAD
        key = IntIntPair(remabove, squareabove)
        if key in self.mem[row]:
            return self.mem[row][key]
        res = self.BAD
        possibilities = 1 << self.cols
        for poss in range(possibilities):
            have = 0
            for j in range(self.cols):
                if ((poss >> j) & 1) == 1:
                    have = self.add(have, j)
            works = True
            for above in range(self.cols):
                if self.contains(remabove, above):
                    if not self.contains(have, above):
                        works = False
                        break
            if works:
                remhere = 0
                for j in range(self.cols):
                    if (not self.contains(have, j - 1) and
                        not self.contains(have, j) and
                        not self.contains(have, j + 1) and
                        not self.contains(squareabove, j)):
                        remhere = self.add(remhere, j)
                res = min(res, self.size(have) + self.dp(row + 1, remhere, have))
        self.mem[row][key] = res
        return res

    def solve(self, testNumber, in_stream):
        self.test()
        n = int(in_stream.readline())
        m = int(in_stream.readline())
        self.cols = min(n, m)
        self.rows = max(n, m)
        self.mem = [defaultdict(int) for _ in range(self.rows)]
        res = self.dp(0, 0, 0)
        print(self.cols * self.rows - res)

def main():
    input_lines = sys.stdin.read().splitlines()
    in_stream = iter(input_lines)
    task = TaskC()
    task.solve(1, in_stream)

if __name__ == "__main__":
    main()

